(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const LIST = '69f8912767effa244dc257bd';
  const list = document.querySelector('[data-list-id="' + LIST + '"]');
  list.querySelector('[data-testid="list-add-card-button"]').click();
  await sleep(600);
  const ta = document.querySelector('[data-testid="list-card-composer-textarea"]');
  if (!ta) return JSON.stringify({err: 'composer não abriu'});
  const setVal = (el, v) => { const proto = HTMLTextAreaElement.prototype; Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, v); el.dispatchEvent(new Event('input', {bubbles: true})); };
  setVal(ta, 'Criar versão Stories dos criativos do workshop Crie seu Site com IA');
  await sleep(400);
  const container = ta.closest('form') || ta.parentElement.parentElement;
  const btn = [...container.querySelectorAll('button')].find(b => /^adicionar cart[ãa]o$/i.test((b.innerText||'').trim()));
  if (!btn) return JSON.stringify({err: 'botão adicionar não achado', btns: [...container.querySelectorAll('button')].map(b => b.innerText.trim()).slice(0,8)});
  btn.click();
  await sleep(2500);
  // verificar via API
  const x = new XMLHttpRequest(); x.open('GET', '/1/lists/' + LIST + '/cards?fields=name,due,dueComplete,id', false); x.send();
  const cards = JSON.parse(x.responseText).filter(c => /versão Stories/i.test(c.name));
  return JSON.stringify({ok: true, criados: cards, total: JSON.parse(x.responseText).length});
})()

